old_logo_pattern = re.compile(
    r'<a class="brand" href="([^"]*)"([^>]*)>\s*<span class="mark">\s*<svg[^>]*>[\s\S]*?</svg>\s*</span>\s*<span>i<b>Can</b>Call</span>\s*</a>'
)

# Also check for one in footers which has no aria-label
old_logo_pattern_footer = re.compile(
    r'<a class="brand" href="([^"]*)">\s*<span class="mark">\s*<svg[^>]*>[\s\S]*?</svg>\s*</span>\s*<span>i<b>Can</b>Call</span>\s*</a>'
)

for name in ['parents', 'seniors', 'caregivers']:
    path = f'scratch/unpacked_{name}/template.html'
    if not os.path.exists(path):
        print(f"Skipping {path} (does not exist)")
        continue
    
    with open(path, 'r', encoding='utf-8') as f:
        html = f.read()
    
    # Replace header logo
    html, n1 = old_logo_pattern.subn(f'<a class="brand" href="\\1"\\2>\n      {new_logo_svg}\n    </a>', html)
    # Replace footer logo
    html, n2 = old_logo_pattern_footer.subn(f'<a class="brand" href="\\1">\n      {new_logo_svg}\n    </a>', html)
    
    print(f"[{name}] Replaced {n1} headers and {n2} footers logo.")
    
    with open(path, 'w', encoding='utf-8') as f:
        f.write(html)
